mapper.select:
SELECT t.log_id, t.product, t.agent, t.job_id, t.job_result, t.begin_time, t.end_time, SUBSTR((TO_TIMESTAMP(t.end_time, 'YYYY-MM-DD HH24:MI:SS,FF') - TO_TIMESTAMP(t.begin_time, 'YYYY-MM-DD HH24:MI:SS,FF')),11,13) spend_time from ww_cron_log t where 1 = 1
and t.job_id = #{jobId}
and to_date(substr(t.begin_time,1,10),'yyyy-MM-dd') >= to_date(#{startTime},'yyyy-MM-dd')
and to_date(substr(t.end_time,1,10),'yyyy-MM-dd') <= to_date(#{endTime},'yyyy-MM-dd')
and t.job_result = #{result}
and t.product = #{product}
and instr(t.agent, #{lAgent}) > 0
and exists ( select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id and tp.p_id=t.product and tsu.login_name=#{loginName} )
order by t.begin_time desc

SELECT t.log_id, t.product, t.agent, t.job_id, t.job_result, t.begin_time, t.end_time, REPLACE(SUBSTR(TIMEDIFF(REPLACE(t.end_time,',','.'),REPLACE(t.begin_time,',','.')),1,12),'.',',') spend_time from ww_cron_log t where 1 = 1
and t.job_id = #{jobId}
and DATE_FORMAT(t.begin_time,'%Y-%m-%d') >= DATE_FORMAT(#{startTime},'%Y-%m-%d')
and DATE_FORMAT(t.end_time,'%Y-%m-%d') <= DATE_FORMAT(#{endTime},'%Y-%m-%d')
and t.job_result = #{result}
and t.product = #{product}
and instr(t.agent, #{lAgent}) > 0
and exists ( select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id and tp.p_id=t.product and tsu.login_name=#{loginName} )
order by t.begin_time desc
